const log = $json;
const event = $node["Parse Log Message"].json.event;
const userId = $node["Parse Log Message"].json.user_id;
const timestamp = new Date($node["Parse Log Message"].json.timestamp).toLocaleString();

const logMessage = `[${timestamp}] ${event} - User: ${userId || 'N/A'}`;

console.log('📝 LOG:', logMessage);

return {
  logged: true,
  message: logMessage
};
